int sa_input_system_configure(ARGS);int sa_input_backend_reset(ARGS);int sa_input_retry_limit_set(ARGS);int sa_input_system_type_set(ARGS);int sa_input_system_initialize(ARGS);int sa_memory_fill(ARGS);int sa_input_packet_mode_set(ARGS);
